#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int INF = 0x3f3f3f3f;
const int T = 99;
const int C = 15;

struct Edge {
    int to, rev;
    ll cap, cost;
};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> g;
    vector<ll> pot, dist;
    vector<int> prevv, preve;

    MinCostFlow(int n_) : n(n_), g(n_), pot(n_, 0), dist(n_), prevv(n_), preve(n_) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size() - 1, 0, -cost});
    }

    ll min_cost_flow(int s, int t, ll maxf) {
        ll res = 0;
        ll flow = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            // Dijkstra with std::set (like a priority queue but using set)
            set<pair<ll,int>> pq;
            pq.insert({0, s});
            while (!pq.empty()) {
                auto it = pq.begin();
                ll d = it->first;
                int v = it->second;
                pq.erase(it);
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + pot[v] - pot[e.to]) {
                        pq.erase({dist[e.to], e.to});
                        dist[e.to] = dist[v] + e.cost + pot[v] - pot[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.insert({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] >= INF) break;
            for (int v = 0; v < n; ++v) pot[v] += dist[v];
            ll add = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                add = min(add, g[prevv[v]][preve[v]].cap);
            }
            flow += add;
            res += add * pot[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
            }
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int source = 0;
    const int sink = n * T + 1;
    MinCostFlow mcf(n * T + 2);

    for (int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        mcf.add_edge(source, a, 1, 0);
    }

    for (int t = 0; t < T; ++t) {
        mcf.add_edge(1 + t * n, sink, INF, 0);
        if (t > 0) {
            for (int i = 1; i <= n; ++i) {
                mcf.add_edge(i + (t-1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; ++j) {
            int cost = (j+1)*(j+1) - j*j;
            for (int t = 1; t < T; ++t) {
                mcf.add_edge(a + (t-1) * n, b + t * n, 1, cost * d + c);
                mcf.add_edge(b + (t-1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll price = mcf.min_cost_flow(source, sink, k);
    cout << price << '\n';

    return 0;
}
